import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, PointLight } = ctx.THREE;

  // 1. Root Container
  const group = new Group();

  // Pick colors from visual spec
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Materials & Geometries trackers for cleanup
  const disposables = [];

  // 2. Local Studio Lighting (Accent rim light for product-shot aesthetics)
  const rimLight = new PointLight(colors.accent, 1.2, 5);
  rimLight.position.set(1.5, 1, 0.5);
  group.add(rimLight);

  // 3. Card Base Plane (Engineered gradient surface & metalness)
  const plateGeo = new PlaneGeometry(2.4, 1.5);
  disposables.push(plateGeo);

  const uColor1 = uniform(ctx.THREE.Color.names ? new ctx.THREE.Color(colors.surface) : new ctx.THREE.Color(colors.surface));
  const uColor2 = uniform(ctx.THREE.Color.names ? new ctx.THREE.Color(colors.ink) : new ctx.THREE.Color(colors.ink));
  const uAccent = uniform(ctx.THREE.Color.names ? new ctx.THREE.Color(colors.accent) : new ctx.THREE.Color(colors.accent));

  const plateMaterial = new MeshStandardNodeMaterial();

  // Custom TSL Shader: Diagonal gradient + Subtle accent border frame
  const coords = uv();
  const grad = smoothstep(0.0, 1.2, coords.x.add(coords.y).div(2.0));
  const baseGrad = mix(uColor1, uColor2, grad);

  // Clean technical border lines
  const borderX = smoothstep(0.0, 0.015, coords.x).mul(smoothstep(1.0, 0.985, coords.x));
  const borderY = smoothstep(0.0, 0.025, coords.y).mul(smoothstep(1.0, 0.975, coords.y));
  const borderFactor = borderX.mul(borderY);

  plateMaterial.colorNode = mix(uAccent, baseGrad, borderFactor);
  plateMaterial.roughness = 0.52;
  plateMaterial.metalness = 0.5;
  disposables.push(plateMaterial);

  const plateMesh = new Mesh(plateGeo, plateMaterial);
  plateMesh.position.set(0, 0, -0.01);
  group.add(plateMesh);

  // 4. Load & Setup Decorative Image ("orb-decor.png")
  if (config.imageUrl) {
    const decorGeo = new PlaneGeometry(1.0, 1.0);
    disposables.push(decorGeo);

    const decorMat = new MeshStandardNodeMaterial({
      transparent: true,
      roughness: 0.2,
      metalness: 0.1
    });
    disposables.push(decorMat);

    const decorMesh = new Mesh(decorGeo, decorMat);
    decorMesh.position.set(0.6, 0.1, 0.01);
    group.add(decorMesh);

    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      decorMat.map = texture;
      decorMat.needsUpdate = true;
    }).catch((err) => {
      console.warn('Failed to load pricing label image:', err);
    });
  }

  // 5. Build and Bind Typography ("Pricing 1")
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const mainText = textItems[0]?.text ?? "Pricing 1";

  const textNode = ctx.fontAtlas.createText(mainText, {
    fontSize: 39,
    color: colors.paper,
    align: 'left'
  });

  // Position text nicely within label bounding context
  textNode.position.set(-1.0, -0.1, 0.02);
  group.add(textNode);

  // 6. Technical Accents (Engineered Atelier micro-ruler lines)
  const lineGeo = new PlaneGeometry(0.12, 0.01);
  const lineMat = new MeshStandardNodeMaterial({ color: colors.accent, roughness: 0.5 });
  disposables.push(lineGeo, lineMat);

  const techTick = new Mesh(lineGeo, lineMat);
  techTick.position.set(-1.0, 0.25, 0.02);
  group.add(techTick);

  // 7. Micro-motion entry (GSAP)
  const tl = gsap.timeline();
  group.position.y += 0.15;
  group.scale.set(0.95, 0.95, 0.95);

  tl.to(group.position, {
    y: '-=0.15',
    duration: 0.8,
    ease: 'power3.out'
  });
  tl.to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out'
  }, '<');

  // 8. Event API & Cleanup
  group.userData = {
    handlers: {},
    cleanup: () => {
      tl.kill();
      disposables.forEach((resource) => {
        if (resource.dispose) resource.dispose();
      });
    }
  };

  return group;
}
